package com.cardv.shared

/**
 * Build information shared by every app.
 *
 * Kept deliberately tiny: this is the scaffolding marker that proves the Android app and the
 * Apple framework link against the shared module.
 */
object BuildInfo {
    /** From `version.xcconfig` at the repository root; generated by :shared:generateBuildInfo. */
    const val VERSION: String = GeneratedBuildInfo.VERSION
    const val APP_NAME: String = "CarDV Dashcam"
}
